	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/signup", wrapper.Signup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/refresh", wrapper.Refresh)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/dev-users", wrapper.ListDevUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/dev-login", wrapper.DevLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/cli/authorize", wrapper.AuthorizeCli)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/cli/token", wrapper.ExchangeCliCode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/devices", wrapper.ListDevices)
